// validateVPCFlags checks that --vpc and --vpc-subnet are used together.
func validateVPCFlags(vpcNameOrID string, subnets []string) error {
	if vpcNameOrID == "" && len(subnets) > 0 {
		return fmt.Errorf("--vpc is required when --vpc-subnet is specified")
	}
	if vpcNameOrID != "" && len(subnets) == 0 {
		return fmt.Errorf("at least one --vpc-subnet is required when --vpc is specified")
	}
	return nil
}

// resolveVPC resolves a VPC NAME|ID and a list of Subnet NAME|IDs to their IDs.
func resolveVPC(
	ctx context.Context,
	client *v3.Client,
	vpcNameOrID string,
	subnets []string,
) (v3.UUID, []v3.UUID, error) {
	vpcEntry, err := vpc.FindVPC(ctx, client, vpcNameOrID)
	if err != nil {
		return "", nil, err
	}

	vpcSubnets, err := client.ListSubnets(ctx, vpcEntry.ID)
	if err != nil {
		return "", nil, fmt.Errorf("error listing VPC Subnets: %w", err)
	}

	subnetIDs := make([]v3.UUID, 0, len(subnets))
	for _, nameOrID := range subnets {
		subnet, err := vpcSubnets.FindListSubnetEntry(nameOrID)
		if err != nil {
			if errors.Is(err, v3.ErrNotFound) {
				return "", nil, fmt.Errorf("subnet %q not found in VPC %q", nameOrID, vpcNameOrID)
			}
			return "", nil, fmt.Errorf("error retrieving VPC Subnet: %w", err)
		}
		subnetIDs = append(subnetIDs, subnet.ID)
	}

	return vpcEntry.ID, subnetIDs, nil
}

// formatVPCSubnets returns the names of the Instance Pool VPC Subnets,
// falling back to the Subnet ID when it is not part of the listed Subnets.
func formatVPCSubnets(poolVPC *v3.InstancePoolVpc, listed []v3.ListSubnetEntry) []string {
	out := make([]string, 0)
	if poolVPC == nil {
		return out
	}

	names := make(map[v3.UUID]string, len(listed))
	for _, s := range listed {
		names[s.ID] = s.Name
	}

	for _, s := range poolVPC.Subnets {
		if name, ok := names[s.ID]; ok && name != "" {
			out = append(out, name)
			continue
		}
		out = append(out, s.ID.String())
	}

	return out
}
